("PDFF","proton-density fat fraction","MRI-based fraction of liver signal from fat; the usual reference standard for ultrasound steatosis measures.",32),
("FOV","field of view","The region of tissue the image covers (depth × width or sector angle).",31),
("FA","false alarm","A detection declared where no true target exists; traded against missed detections by the threshold.",31,[31]),
("FR","frame rate","Images formed per second; limited by depth, lines or transmits per frame and processing.",31,[28,31]),
("PEG","polyethylene glycol","Polymer brush grafted to lipid microbubble shells to stabilize them and reduce clearance.",28),
("A0","zeroth-order antisymmetric Lamb mode","Flexural guided wave in a plate; its dispersion is used in shear-wave elastography of thin tissues.",30,[30]),
("CAF","coarse array factor","Array factor of the subarray centres in a micro-beamformed array; its grating lobes are set by the subarray pitch.",19,[19]),
("SF","subarray factor","Beam pattern of one subarray; multiplies the coarse array factor in a micro-beamformed array.",19,[19]),
("GB","gigabyte","10⁹ bytes; used for channel-data volumes and memory sizes.",20),
("FDORA","Food and Drug Omnibus Reform Act of 2022","U.S. law whose section 3308 added FD&C Act section 515C, the statutory basis for predetermined change control plans (PCCPs).",36),
("GMLP","good machine learning practice","FDA, Health Canada and MHRA guiding principles (2021) for developing machine-learning-enabled medical devices.",36),
("MHRA","Medicines and Healthcare products Regulatory Agency","The UK regulator for medicines and medical devices.",36),
("GUDID","Global Unique Device Identification Database","FDA database of device-identifier records that labelers submit under 21 CFR 830.",36),
("UDI-DI","UDI device identifier","Static part of a UDI that identifies the labeler and the model or version; the EU's Basic UDI-DI is the model-level key in EUDAMED.",36),
